import{_ as a,o as i,c as t,a5 as r}from"./chunks/framework.DrDMl0tG.js";const v=JSON.parse('{"title":"Changelog: v2.5","description":"","frontmatter":{},"headers":[],"relativePath":"sections/changelog/v2.5.md","filePath":"sections/changelog/v2.5.md"}'),s={name:"sections/changelog/v2.5.md"};function o(l,e,n,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="changelog-v2-5" tabindex="-1">Changelog: v2.5 <a class="header-anchor" href="#changelog-v2-5" aria-label="Permalink to &quot;Changelog: v2.5&quot;">​</a></h1><h2 id="v2-5-8-2026-09-04" tabindex="-1">v2.5.8 (2026-09-04) <a class="header-anchor" href="#v2-5-8-2026-09-04" aria-label="Permalink to &quot;v2.5.8 (2026-09-04)&quot;">​</a></h2><ul><li>rayrai: mesh GPU buffers shared across GL contexts (no VRAM growth per render thread); windows created on a thread with a current context join its share group.</li><li><code>RayraiGlobalAsset</code> shared GPU-asset cache controls and <code>sharedGpuAssetStats</code>.</li><li>Async RGB/depth readback uses the full PBO ring; fixed worker cameras sharing a depth texture.</li></ul><h2 id="v2-5-7-2026-09-03" tabindex="-1">v2.5.7 (2026-09-03) <a class="header-anchor" href="#v2-5-7-2026-09-03" aria-label="Permalink to &quot;v2.5.7 (2026-09-03)&quot;">​</a></h2><ul><li>rayrai: no &quot;ghost&quot; objects when a removed object&#39;s address is reused (stable <code>Object::Id</code>); camera drops a removed target.</li><li>Linux installer confirms before deleting old installs and retries with <code>sudo</code>.</li></ul><h2 id="v2-5-6-2026-09-02" tabindex="-1">v2.5.6 (2026-09-02) <a class="header-anchor" href="#v2-5-6-2026-09-02" aria-label="Permalink to &quot;v2.5.6 (2026-09-02)&quot;">​</a></h2><ul><li>TCP viewer: per-camera frustum and frame toggles.</li><li><code>&quot;hidden&quot;</code>/<code>&quot;invisible&quot;</code> appearance removes an object from rendering.</li><li>Fixed removed heightmaps in depth renders; protocol reader rejects oversized lengths.</li><li>Faster contact-solver iterations and warm-start lookups.</li></ul><h2 id="v2-5-5-2026-08-30" tabindex="-1">v2.5.5 (2026-08-30) <a class="header-anchor" href="#v2-5-5-2026-08-30" aria-label="Permalink to &quot;v2.5.5 (2026-08-30)&quot;">​</a></h2><ul><li>TCP viewer renders the server&#39;s <code>MANUAL</code> RGB/depth sensors and shows previews and frustums.</li><li>Live Signals graphs, replay seek, network diagnostics; server-side record/screenshot/window-size commands.</li><li><code>PROTOCOL_FEATURE_CONTACT_OBJECT_TAGS</code>.</li><li>Sensors keep updating while their system sleeps or is fixed.</li><li>Depth rendering can include custom/instanced visuals.</li><li>TCP viewer ships as example source; <code>RAISIM_VISUALIZER_INSTALL</code> removed.</li></ul><h2 id="v2-5-4-2026-08-29" tabindex="-1">v2.5.4 (2026-08-29) <a class="header-anchor" href="#v2-5-4-2026-08-29" aria-label="Permalink to &quot;v2.5.4 (2026-08-29)&quot;">​</a></h2><ul><li>Heightmap contacts: wheels no longer sink or tunnel on steps, contacts match the triangulated surface, buried bodies recover smoothly.</li><li>TCP viewer saves the user UI scale.</li><li>No C++20 <code>&lt;bit&gt;</code> dependency; <code>Mesh</code>/<code>World</code> ABI guard.</li></ul><h2 id="v2-5-3-2026-08-24" tabindex="-1">v2.5.3 (2026-08-24) <a class="header-anchor" href="#v2-5-3-2026-08-24" aria-label="Permalink to &quot;v2.5.3 (2026-08-24)&quot;">​</a></h2><ul><li>Faster heightmap–primitive (bit-identical) and heightmap–mesh contacts.</li><li>Reproducible contacts across builds (<code>-ffp-contract=on</code>); <code>CONFIGURE_DEPENDS</code> globs; MSVC fix.</li></ul><h2 id="v2-5-2-2026-08-22" tabindex="-1">v2.5.2 (2026-08-22) <a class="header-anchor" href="#v2-5-2-2026-08-22" aria-label="Permalink to &quot;v2.5.2 (2026-08-22)&quot;">​</a></h2><ul><li>Heightmap fixes: no false contacts above the surface or across seams, thin/tiny shapes near the boundary, buried primitives, large translations, stale contacts after updates.</li><li>Clients can connect during a busy simulation; faster TCP viewer mesh batching.</li></ul><h2 id="v2-5-1-2026-08-20" tabindex="-1">v2.5.1 (2026-08-20) <a class="header-anchor" href="#v2-5-1-2026-08-20" aria-label="Permalink to &quot;v2.5.1 (2026-08-20)&quot;">​</a></h2><ul><li>Fixed missed heightmap contacts with box edges and cylinder sides/caps.</li><li>Faster large heightmaps in the TCP viewer; heightmap no longer sent twice.</li><li><code>Visuals::notifyMeshMaterialsChanged</code>.</li></ul><h2 id="v2-5-0-2026-08-18" tabindex="-1">v2.5.0 (2026-08-18) <a class="header-anchor" href="#v2-5-0-2026-08-18" aria-label="Permalink to &quot;v2.5.0 (2026-08-18)&quot;">​</a></h2><ul><li><code>World::rayTest</code> uses a lazily rebuilt BVH.</li><li><code>World::rayTestLidar</code> ~12.5× faster per ray (28 ns vs 355 ns).</li><li><strong>Breaking:</strong> <code>rayTestLidar</code> takes yaw/pitch start, increment and count.</li></ul>',19)])])}const m=a(s,[["render",o]]);export{v as __pageData,m as default};
